const int BTN_PIN = 2;
const int LED_PIN = 8;
const int BUZ_PIN = 9;

#define NOTE_G4  392
#define NOTE_A4  440
#define NOTE_B4  494
#define NOTE_C5  523
#define NOTE_D5  587
#define NOTE_E5  659
#define NOTE_F5  698
#define NOTE_G5  784

int melody[] = {
  NOTE_G4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_C5, NOTE_B4, 0,
  NOTE_G4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_D5, NOTE_C5, 0,
  NOTE_G4, NOTE_G4, NOTE_G5, NOTE_E5, NOTE_C5, NOTE_B4, NOTE_A4, 0,
  NOTE_F5, NOTE_F5, NOTE_E5, NOTE_C5, NOTE_D5, NOTE_C5, 0
};

int durations[] = {
  4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 2, 4
};

bool lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50; 

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZ_PIN, OUTPUT);
  Serial.begin(115200);
  
  // ТЕСТ: Короткий писк при включении платы
  tone(BUZ_PIN, 1000, 200); 
  delay(200);
  noTone(BUZ_PIN);
}

void loop() {
  bool reading = digitalRead(BTN_PIN);

  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading == LOW) {
      Serial.println("Кнопка нажата! Играем мелодию...");
      playMelody();
      Serial.println("Мелодия закончилась.");
    }
  }
  lastButtonState = reading;
}

void playMelody() {
  digitalWrite(LED_PIN, HIGH);
  int numNotes = sizeof(melody) / sizeof(melody[0]);

  for (int i = 0; i < numNotes; i++) {
    int noteDuration = 1000 / durations[i];
    
    if (melody[i] != 0) {
      tone(BUZ_PIN, melody[i], noteDuration);
    }
    
    // Ждем. 1.3 - это пауза между нотами
    delay(noteDuration * 1.3); 
    noTone(BUZ_PIN);
  }
  digitalWrite(LED_PIN, LOW);
}
